package ama.api;
import ama.contract.IdentityContracts.*;import ama.transcript.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Actual HTTP parsing/dispatch; assembly and receipt boundaries are substitutes, not runtime qualification. */
class Task11MinutesActivationDispatchTest {
 static final String M="12345678-1234-4234-8234-123456789abc",T="12345678-1234-4234-8234-123456789abd";
 final JdbcMinutesIntentReceipts intents=mock(JdbcMinutesIntentReceipts.class);final JdbcMinutesSettingsReceipts settings=mock(JdbcMinutesSettingsReceipts.class);final JdbcMinutesGenerationReceipts generations=mock(JdbcMinutesGenerationReceipts.class);
 final MinutesEditorRuntime editor=mock(MinutesEditorRuntime.class);final JdbcMinutesEditor intentService=mock(JdbcMinutesEditor.class);final JdbcMinutesInitialSettings initial=mock(JdbcMinutesInitialSettings.class);final JdbcMinutesGenerationCommands generation=mock(JdbcMinutesGenerationCommands.class);final JdbcMinutesQueries queries=mock(JdbcMinutesQueries.class);
 final Actor actor=new Actor("owner",Status.ACTIVE,Set.of(Role.USER));
 MockMvc mvc(boolean installed){var runtime=new MinutesConfiguration.Runtime(installed?editor:null,null,installed?queries:null,installed?initial:null,installed?generation:null,null,null,null,65536);return MockMvcBuilders.standaloneSetup(new MinutesController(intents,runtime,settings,generations,null,null)).setControllerAdvice(new MinutesErrors()).build();}
 org.springframework.mock.web.MockHttpServletResponse call(String route,String body,boolean installed)throws Exception{return mvc(installed).perform(post("/api/v1/meetings/"+M+"/minutes/"+route).requestAttr(SessionSecurityFilter.SESSION,new ResolvedSession(actor,"T".repeat(43),Instant.now().plusSeconds(60))).header("Idempotency-Key","activation-key").contentType("application/json").content(body)).andReturn().getResponse();}
 @Test void receiptMissDispatchesEachRealRouteAfterAssemblyGate()throws Exception{
  when(editor.editor()).thenReturn(intentService);when(intentService.intent(actor,M,"activation-key",7)).thenReturn(Map.of("intentEpochToken","2"));when(initial.initialize(eq(actor),eq(M),eq("activation-key"),eq(7L),eq(T),anyString())).thenReturn(Map.of("initialized",true));when(generation.enqueue(eq(actor),eq(M),eq("activation-key"),eq(7L),anyString())).thenReturn(Map.of("taskId","accepted-task"));
  assertEquals(200,call("editor-intents","{\"expectedRevisionToken\":\"7\"}",true).getStatus());assertEquals(200,call("initial-settings","{\"expectedRevisionToken\":\"7\",\"templateRevisionId\":\""+T+"\"}",true).getStatus());var response=call("generations","{\"expectedRevisionToken\":\"7\",\"scope\":\"FULL\"}",true);assertEquals(202,response.getStatus());assertEquals("private, no-store",response.getHeader("Cache-Control"));verify(intentService).intent(actor,M,"activation-key",7);verify(generation).enqueue(eq(actor),eq(M),eq("activation-key"),eq(7L),anyString());
 }
 @Test void acceptedReceiptStillPrecedesAbsentAssembly()throws Exception{when(intents.lookup(actor,M,"activation-key",7)).thenReturn(Optional.of(Map.of("replayed",true)));assertEquals(200,call("editor-intents","{\"expectedRevisionToken\":\"7\"}",false).getStatus());verifyNoInteractions(editor,initial,generation);}
 @Test void genuineMissWithoutAssemblyStaysUnavailable()throws Exception{assertEquals(503,call("editor-intents","{\"expectedRevisionToken\":\"7\"}",false).getStatus());verifyNoInteractions(intentService,initial,generation);} @Test void freshIntentTypedStaleResultRemains409WithCurrentObservation()throws Exception{when(editor.editor()).thenReturn(intentService);var stale=mock(JdbcMinutesIntentReceipts.StaleIntent.class);when(stale.response()).thenReturn(Map.of("error",Map.of("code","REVISION_CONFLICT"),"current",Map.of("revisionToken","8")));when(intentService.intent(actor,M,"activation-key",7)).thenThrow(stale);var result=call("editor-intents","{\"expectedRevisionToken\":\"7\"}",true);assertEquals(409,result.getStatus());assertTrue(result.getContentAsString().contains("revisionToken"));assertEquals("private, no-store",result.getHeader("Cache-Control"));}
}
